<div class="step-form review-step">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <div class="success-icon">✓</div>
            <h4>Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>We'll be in touch soon. Thank you for applying!</p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="validation-error" role="alert">@ErrorMessage</div>
        }

        <section class="review-section">
            <div class="review-section-header">
                <h4>Personal Information</h4>
                <button class="btn-link" @onclick="() => EditStep(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@PersonalFullName</dd>
                <dt>Email</dt><dd>@PersonalEmail</dd>
                <dt>Phone</dt><dd>@PersonalPhone</dd>
                <dt>Address</dt><dd>@PersonalAddress</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h4>Work History</h4>
                <button class="btn-link" @onclick="() => EditStep(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="date-range">
                        @entry.StartDate.ToString("MMM yyyy") –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h4>References</h4>
                <button class="btn-link" @onclick="() => EditStep(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-entry">
                    <strong>@r.Name</strong> — @r.Relationship
                    <br />@r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $" | {r.Phone}" : "")
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-section-header">
                <h4>Cover Letter</h4>
                <button class="btn-link" @onclick="() => EditStep(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@(string.IsNullOrWhiteSpace(CoverLetter) ? "(No cover letter provided)" : CoverLetter)</p>
        </section>

        <div class="step-buttons">
            <button class="btn btn-outline" @onclick="OnBack">Back</button>
            <button class="btn btn-primary btn-submit" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @(IsSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public string PersonalFullName { get; set; } = "";
    [Parameter] public string PersonalEmail { get; set; } = "";
    [Parameter] public string PersonalPhone { get; set; } = "";
    [Parameter] public string PersonalAddress { get; set; } = "";
    [Parameter] public List<WorkEntryForm.WorkEntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferenceForm.ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int? ApplicationId;
    private string? ErrorMessage;

    // Set by parent after submission
    [Parameter] public int? SubmittedApplicationId { get; set; }

    protected override void OnParametersSet()
    {
        if (SubmittedApplicationId.HasValue && !IsSubmitted)
        {
            IsSubmitted = true;
            ApplicationId = SubmittedApplicationId;
            IsSubmitting = false;
        }
    }

    private async Task EditStep(int step)
    {
        await OnEditStep.InvokeAsync(step);
    }

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        ErrorMessage = null;
        StateHasChanged();

        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
