@page "/apply"
@namespace sv_f868f5bc079e4cae8ed7348ab84b9bdb.Components.Pages.Apply
@rendermode InteractiveServer
@using sv_f868f5bc079e4cae8ed7348ab84b9bdb.Services

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form-container">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@_currentStep"
                   CompletedSteps="@_completedSteps"
                   OnStepSelected="GoToStep" />

    <div class="step-content">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@_fullName"
                                  Email="@_email"
                                  Phone="@_phone"
                                  Address="@_address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalInfoNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="@_workEntries"
                                 OnNext="HandleWorkHistoryNext"
                                 OnBack="GoBack" />
                break;

            case 2:
                <ReferencesStep References="@_references"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="@_coverLetter"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;

            case 4:
                <ReviewStep PersonalFullName="@_fullName"
                            PersonalEmail="@_email"
                            PersonalPhone="@_phone"
                            PersonalAddress="@_address"
                            WorkEntries="@_workEntries"
                            References="@_references"
                            CoverLetter="@_coverLetter"
                            SubmittedApplicationId="@_submittedId"
                            OnBack="GoBack"
                            OnEditStep="GoToStep"
                            OnSubmit="HandleSubmit" />
                break;
        }
    </div>
</div>

@code {
    private int _currentStep = 0;
    private HashSet<int> _completedSteps = new();

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> _workEntries = new() { new() };

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> _references = new() { new(), new() };

    // Step 4 state
    private string _coverLetter = "";

    // Submission state
    private int? _submittedId;

    private void HandlePersonalInfoNext((string FullName, string Email, string Phone, string Address) data)
    {
        _fullName = data.FullName;
        _email = data.Email;
        _phone = data.Phone;
        _address = data.Address;
        CompleteAndAdvance(0);
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        _workEntries = entries;
        CompleteAndAdvance(1);
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> references)
    {
        _references = references;
        CompleteAndAdvance(2);
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        CompleteAndAdvance(3);
    }

    private async Task HandleSubmit()
    {
        var application = new Models.JobApplication(
            new Models.PersonalInfo(_fullName, _email, _phone, _address),
            new Models.WorkHistory(_workEntries.Select(e => new Models.WorkEntry(
                e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
            )).ToList()),
            _references.Select(r => new Models.Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            _coverLetter
        );

        _submittedId = await ApplicationService.SubmitApplicationAsync(application);
        _completedSteps.Add(4);
    }

    private void CompleteAndAdvance(int step)
    {
        _completedSteps.Add(step);
        _currentStep = step + 1;
    }

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0)
            _currentStep--;
    }
}

.application-form-container {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.application-form-container h2 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
