}

.step-item.active .step-circle {
    background: #2563eb;
    border-color: #2563eb;
    color: white;
}

.step-item.completed .step-circle {
    background: #10b981;
    border-color: #10b981;
    color: white;
}

.step-item.dimmed .step-circle {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
    color: #6b7280;
    text-align: center;
    white-space: nowrap;
}

.step-item.active .step-label {
    color: #2563eb;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #10b981;
}

.step-item.dimmed .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #d1d5db;
    min-width: 30px;
    max-width: 60px;
    margin: 0 0.25rem;
    margin-bottom: 1.5rem;
}

.step-connector.completed {
    background: #10b981;
}

.checkmark {
    font-size: 1rem;
}

