    margin-bottom: 1rem;
    background: #f9fafb;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h4 {
    margin: 0;
    color: #374151;
}

/* Character Count */
.char-count {
    text-align: right;
    font-size: 0.8125rem;
    color: #6b7280;
    margin-top: 0.375rem;
}

.char-count.over-limit {
    color: #dc2626;
    font-weight: 500;
}

/* Review Step */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #e5e7eb;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section-header h4 {
    margin: 0;
    color: #1a1a2e;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.5rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #6b7280;
    font-size: 0.875rem;
}

.review-section dd {
    margin: 0;
    color: #1f2937;
}

.review-entry {
    padding: 0.75rem;
    background: #f9fafb;
    border-radius: 4px;
    margin-bottom: 0.5rem;
}

.date-range {
    font-size: 0.8125rem;
    color: #6b7280;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f9fafb;
    padding: 1rem;
    border-radius: 4px;
    font-size: 0.9375rem;
    line-height: 1.6;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.success-icon {
    width: 64px;
    height: 64px;
    background: #10b981;
    color: white;
    border-radius: 50%;
