}

.submission-confirmation h4 {
    font-size: 1.25rem;
    color: #1a1a2e;
    margin-bottom: 0.5rem;
}

.submission-confirmation p {
    color: #6b7280;
    font-size: 1rem;
}

/* Responsive */
@media (max-width: 640px) {
    .form-row {
        grid-template-columns: 1fr;
    }

    .step-label {
        display: none;
    }

    .step-connector {
        min-width: 20px;
    }
}

