+}
+
+.review-section dd {
+    margin: 0;
+    color: #1f2937;
+}
+
+.review-entry {
+    padding: 0.75rem;
+    background: #f9fafb;
+    border-radius: 4px;
+    margin-bottom: 0.5rem;
+}
+
+.date-range {
+    font-size: 0.8125rem;
+    color: #6b7280;
+}
+
+.cover-letter-preview {
