@namespace sv_f868f5bc079e4cae8ed7348ab84b9bdb.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="HandleRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @oninput="e => UpdateEntry(Entry with { Company = e.Value?.ToString() ?? "" })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @oninput="e => UpdateEntry(Entry with { Title = e.Value?.ToString() ?? "" })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")" @onchange="e => UpdateEndDate(e.Value?.ToString())" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentToggle" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @oninput="e => UpdateEntry(Entry with { Description = e.Value?.ToString() ?? "" })" rows="3" placeholder="Describe your responsibilities..."></textarea>
    </div>
</div>

@code {
    [Parameter] public WorkEntryModel Entry { get; set; } = new();
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private async Task UpdateEntry(WorkEntryModel updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task UpdateEndDate(string? value)
    {
        if (DateTime.TryParse(value, out var date))
        {
            await UpdateEntry(Entry with { EndDate = date });
        }
    }

    private async Task HandleCurrentToggle(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        await UpdateEntry(Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate });
    }

    private async Task HandleRemove()
    {
        await OnRemove.InvokeAsync();
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

