        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @oninput="OnCompanyInput" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @oninput="OnTitleInput" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="OnStartDateChange" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@EndDateValue" @onchange="OnEndDateChange" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentToggle" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @oninput="OnDescriptionInput" rows="3" placeholder="Describe your responsibilities..."></textarea>
    </div>
</div>

@code {
    [Parameter] public WorkEntryModel Entry { get; set; } = new();
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;
    private string EndDateValue => Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty;

    private Task OnCompanyInput(ChangeEventArgs e)
    {
        Entry.Company = e.Value?.ToString() ?? "";
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task OnTitleInput(ChangeEventArgs e)
    {
        Entry.Title = e.Value?.ToString() ?? "";
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task OnDescriptionInput(ChangeEventArgs e)
    {
        Entry.Description = e.Value?.ToString() ?? "";
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task OnStartDateChange(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
        {
            Entry.StartDate = date;
        }
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task OnEndDateChange(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
        {
            Entry.EndDate = date;
        }
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task HandleCurrentToggle(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        Entry.IsCurrent = isCurrent;
        if (isCurrent) Entry.EndDate = null;
        return OnEntryChanged.InvokeAsync(Entry);
    }

    private Task HandleRemove() => OnRemove.InvokeAsync();

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

